"""用户路由：注册、登录、获取当前用户。"""
from fastapi import APIRouter, HTTPException, Depends

from app.database import Session, create_session
from app.models import User
from app.schemas import UserRegister, UserLogin, UserOut, TokenOut
from app.core.auth import hash_password, verify_password, generate_token, store_token, require_user

router = APIRouter(prefix="/api/users", tags=["users"])


def get_db():
    db = create_session()
    try:
        yield db
    finally:
        db.close()


def _user_out(user: User) -> dict:
    return {"id": user.id, "username": user.username, "role": user.role}


@router.post("/register", response_model=UserOut)
def register(body: UserRegister, db: Session = Depends(get_db)):
    if body.role not in ("admin", "user"):
        raise HTTPException(400, "role 必须为 admin 或 user")
    if db.query(User).filter(User.username == body.username).first() is not None:
        raise HTTPException(400, "用户名已存在")
    user = User(
        username=body.username,
        password_hash=hash_password(body.password),
        role=body.role,
    )
    db.add(user)
    db.commit()
    db.refresh(user)
    return _user_out(user)


@router.post("/login", response_model=TokenOut)
def login(body: UserLogin, db: Session = Depends(get_db)):
    user = db.query(User).filter(User.username == body.username).first()
    if user is None or not verify_password(body.password, user.password_hash):
        raise HTTPException(401, "用户名或密码错误")
    token = generate_token()
    store_token(token, user.id)
    return {"token": token, "user": _user_out(user)}


@router.get("/me", response_model=UserOut)
def me(user: User = Depends(require_user)):
    return _user_out(user)

